from itertools import product

U = range(3)
subsets = [frozenset(i for i in U if m >> i & 1) for m in range(8)]

def some_not(X, Y): return len(X - Y) > 0      # some X are not Y
def not_all(X, Y):  return not (X <= Y)        # not all X are Y

# each option: (premise, conclusion) as functions of (X, Y)
orig = (lambda X, Y: some_not(X, Y), lambda X, Y: not_all(Y, X))
opts = {
    "A": (lambda X, Y: not_all(X, Y), lambda X, Y: some_not(Y, X)),
    "B": (lambda X, Y: some_not(X, Y), lambda X, Y: not_all(X, Y)),
    "C": (lambda X, Y: some_not(X, Y), lambda X, Y: some_not(Y, X)),
    "D": (lambda X, Y: some_not(X, Y), lambda X, Y: not_all(Y, X)),
}

def valid(arg):
    return all((not arg[0](X, Y)) or arg[1](X, Y)
               for X, Y in product(subsets, repeat=2))

def same_form(a, b):
    return all(a[0](X, Y) == b[0](X, Y) and a[1](X, Y) == b[1](X, Y)
               for X, Y in product(subsets, repeat=2))

print("original argument valid as logic?", valid(orig))
odd = []
for k, a in opts.items():
    sf = same_form(a, orig)
    print(k, "valid:", valid(a), "same form as original:", sf)
    if not sf:
        odd.append(k)

print("Options whose form differs from the original:", odd)
submitted = "C"
if odd == ["B"] and submitted not in odd:
    print("Expected answer: B; submitted answer C is wrong")
    print("CHECK FAIL")
elif odd == [submitted]:
    print("CHECK PASS")
else:
    print("CHECK UNKNOWN")
